<style>
  /* BONAFIT88 Premium Section – Gold & Black 2025 Edition */
  .BONAFIT88-section {
    max-width: 1280px;
    margin: 50px auto;
    padding: 60px 40px;
    background: linear-gradient(135deg, #0d0d0d 0%, #000000 100%);
    border-radius: 24px;
    border: 3px solid #cc5ee7;
    box-shadow: 
      0 0 40px rgba(255, 215, 0, 0.4),
      inset 0 0 40px rgba(255, 215, 0, 0.08);
    position: relative;
    overflow: hidden;
    font-family: "Poppins", sans-serif;
  }

  .BONAFIT88-section h2 {
    text-align: center;
    font-size: 36px;
    font-weight: 900;
    color: #cc5ee7;
    text-shadow: 0 0 15px rgba(255, 215, 0, 0.7);
    margin-bottom: 50px;
    letter-spacing: 1.5px;
    position: relative;
  }

  .BONAFIT88-section h2::after {
    content: "";
    display: block;
    width: 150px;
    height: 4px;
    background: linear-gradient(90deg, transparent, #cc5ee7, transparent);
    margin: 20px auto 0;
    border-radius: 2px;
  }

  /* FAQ – Style baru */
  .faq-grid {
    display: grid;
    gap: 20px;
    max-width: 1000px;
    margin: 0 auto 70px;
  }

  details {
    background: linear-gradient(145deg, #1a1a1a, #0f0f0f);
    border: 2px solid #cc5ee7;
    border-radius: 16px;
    overflow: hidden;
    transition: all 0.4s ease;
  }

  details[open] {
    box-shadow: 0 0 30px rgba(255, 215, 0, 0.5);
  }

  summary {
    padding: 22px 28px;
    font-size: 19px;
    font-weight: 700;
    color: #cc5ee7;
    cursor: pointer;
    background: linear-gradient(90deg, #cc5ee7, #9c0388);
    color: #000;
    position: relative;
  }

  summary::marker { color: #000; }
  summary::-webkit-details-marker { display: none; }

  details p {
    padding: 25px 28px;
    background: #111;
    color: #e0e0e0;
    font-size: 16px;
    line-height: 1.8;
  }

  /* Testimoni – 3 kolom landscape */
  .testi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 30px;
    margin-top: 50px;
  }

  blockquote {
    background: linear-gradient(135deg, #cc5ee7, #9c0388);
    color: #000;
    padding: 30px 28px;
    border-radius: 16px;
    position: relative;
    font-style: italic;
    box-shadow: 0 10px 30px rgba(0,0,0,0.6);
    transition: all 0.4s;
  }

  blockquote:hover {
    transform: translateY(-12px);
    box-shadow: 0 20px 50px rgba(255, 215, 0, 0.4);
  }

  blockquote::before {
    content: "“";
    font-size: 100px;
    font-family: Georgia, serif;
    opacity: 0.2;
    position: absolute;
    top: -10px;
    left: 15px;
    line-height: 1;
  }

  cite {
    display: block;
    margin-top: 20px;
    text-align: right;
    font-weight: 900;
    font-size: 17px;
    color: #000;
  }

  /* Shine effect lebih dramatis */
  .BONAFIT88-section::before {
    content: "";
    position: absolute;
    top: -100%;
    left: -100%;
    width: 60%;
    height: 300%;
    background: linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.4) 50%, transparent 70%);
    transform: skewX(-25deg);
    animation: megaShine 5s infinite;
    pointer-events: none;
  }

  @keyframes megaShine {
    0%   { left: -100%; }
    100% { left: 120%; }
  }
</style>

<div class="BONAFIT88-section">

  <h2>FAQ BONAFIT88 Resmi</h2>

  <div class="faq-grid">
  <details>
    <summary>Apa itu BONAFIT88 bet 200 perak?</summary>
    <p>
      BONAFIT88 bet 200 perak adalah fitur bermain dengan nominal rendah yang memungkinkan pengguna menikmati berbagai game digital dengan modal terjangkau namun tetap seru.
    </p>
  </details>

  <details>
    <summary>Apakah BONAFIT88 bet 200 perak cocok untuk pemula?</summary>
    <p>
      Ya, sistem bet 200 perak di BONAFIT88 sangat cocok untuk pemula karena memberikan risiko lebih kecil dan membantu memahami pola permainan dengan lebih santai.
