<style>
/* ========================================
   MINIMAL MOBILE FIX - Hanya Perbaiki Overflow
   Tidak mengubah desain yang sudah ada
   ======================================== */

/* Hanya fix overflow horizontal */
html {
  max-width: 100vw;
  overflow-x: hidden;
}

body {
  max-width: 100vw;
  overflow-x: hidden;
}

/* Fix images yang terlalu besar */
img {
  max-width: 100%;
  height: auto;
}

/* Fix input zoom di iOS - hanya ubah font size minimum */
@media (max-width: 768px) {
  input[type="text"],
  input[type="search"],
  textarea,
  select {
    font-size: 16px;
  }
  .listing-page-content {
    min-width: 100%;
}
.BONAFIT88-section {
    padding: 5px;
}
.testimkijin2-wrapper {
    gap: 2px;
}
}

/* Accessibility - Reduce motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* SEO Optimization - Keywords meta tag ada di head */


/* SEO Content Styling */
main#main-content {
  padding: 20px 0;
}

article.article-container h1 {
  font-size: 28px;
  font-weight: 700;
  color: #fbe31f;
  margin-bottom: 20px;
  text-align: center;
  text-shadow: 0 0 10px rgba(251, 227, 31, 0.5);
}

article.article-container h2 {
  font-size: 22px;
  font-weight: 600;
  color: #fbe31f;
  margin-top: 25px;
  margin-bottom: 15px;
  border-left: 4px solid #d00f18;
  padding-left: 15px;
}

article.article-container h3 {
  font-size: 18px;
  font-weight: 600;
  color: #ffffff;
  margin-top: 20px;
  margin-bottom: 12px;
}

article.article-container h4 {
  font-size: 16px;
  font-weight: 600;
  color: #c8fff0;
  margin-top: 15px;
  margin-bottom: 8px;
}

article.article-container ul {
  list-style: none;
  padding-left: 20px;
  margin: 15px 0;
}

article.article-container ul li {
  margin: 8px 0;
  color: #c8fff0;
}

/* Responsive heading sizes */
@media (max-width: 600px) {
  article.article-container h1 {
    font-size: 22px;
  }
  
  article.article-container h2 {
    font-size: 18px;
  }
  
  article.article-container h3 {
    font-size: 16px;
  }
}</style>


